	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/auth/reset", wrapper.ResetWithToken)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/overview", wrapper.GetOverview)
